UPDATE Foods SET
Description_VI = 'Bánh mì truyền thống Việt Nam với vỏ bánh giòn rụm, nhân đa dạng gồm chả lụa thơm béo, pâté mịn màng, dưa leo giòn mát, đồ chua chua ngọt, ớt tươi cay nồng và rau thơm xanh mướt. Được chế biến từ những nguyên liệu tươi ngon mỗi ngày, mang đến hương vị đặc trưng không thể nhầm lẫn của ẩm thực đường phố Sài Gòn. Quán nằm trên con phố Vĩnh Khánh sầm uất, phục vụ từ sáng sớm đến tối muộn.',
Description_EN = 'A traditional Vietnamese sandwich featuring a perfectly crispy baguette filled with savory Vietnamese ham, silky pâté, crunchy cucumber, tangy pickled vegetables, fresh chili, and fragrant herbs. Crafted daily from the freshest ingredients, it delivers the unmistakable flavors of Saigon street food. Located on the bustling Vinh Khanh Street, the shop serves from early morning to late evening.',
Description_CN = '传统越南三明治，外壳酥脆的法棍面包，内馅丰富，包括香浓的越南火腿、细腻的肝酱、爽脆的黄瓜、酸甜的腌菜、新鲜辣椒和芳香的香草。每天使用最新鲜的食材手工制作，呈现出西贡街头美食独特而令人难忘的风味。位于热闹的永庆街，从清晨营业到深夜。'
WHERE Name = 'Bánh Mì Trần Văn Hành';

UPDATE Foods SET
Description_VI = 'Bún chả nổi tiếng với thịt nướng thơm lừng trên than hoa, từng miếng thịt được ướp gia vị đậm đà rồi nướng vàng ươm. Nước mắm chua ngọt pha chế theo công thức gia truyền, kết hợp hoàn hảo với bún tươi mát, rau sống dồi dào gồm xà lách, kinh giới, tía tô và nem chiên giòn rụm. Đây là một trong những quán ăn được bạn bè du khách yêu thích nhất trên phố ẩm thực Vĩnh Khánh.',
Description_EN = 'Famous grilled pork noodles with aromatic charcoal-grilled meat, each piece marinated in rich spices and grilled to golden perfection. The dipping sauce is a family-recipe fish sauce with the perfect balance of sweet and sour, paired with fresh rice vermicelli, abundant greens including lettuce, perilla, and basil, plus crispy spring rolls. One of the most beloved eateries among visitors on Vinh Khanh food street.',
Description_CN = '以炭火烤肉闻名的越南烤肉米粉，每块肉都经过浓郁香料腌制后烤至金黄。蘸酱采用家传秘方调制的鱼露，酸甜适中，搭配清爽的米粉、丰富的生菜包括生菜、紫苏和罗勒，以及香脆的春卷。这是永庆美食街上最受游客喜爱的餐厅之一。'
WHERE Name = 'Bún Chả Hàng Cót';

UPDATE Foods SET
Description_VI = 'Cơm tấm được nấu từ những hạt gạo tấm chất lượng cao, hạt cơm tơi xốp thấm đều nước mỡ. Phục vụ kèm sườn nướng mềm ngọt ướp sả ớt, trứng ốp la lòng đào, bì heo giòn sần sật, chả trứng hấp thơm lừng, dưa leo tươi mát và nước mắm chua ngọt được pha chế vừa vặn. Một phần cơm tấm đầy đặn đủ để bạn cảm nhận trọn vẹn tinh hoa ẩm thực Sài Gòn.',
Description_EN = 'Broken rice cooked from premium quality grains, each grain fluffy and perfectly seasoned. Served with tender lemongrass-marinated grilled pork chop, a sunny-side-up egg with runny yolk, crispy shredded pork skin, fragrant steamed egg cake, fresh cucumber, and perfectly balanced fish sauce dip. A generous portion that lets you fully experience the essence of Saigon cuisine.',
Description_CN = '用优质碎米烹制的破碎米饭，每粒米饭松软入味。搭配香茅腌制的嫩烤猪排、半熟煎蛋、脆爽的猪皮丝、香气四溢的蒸蛋糕、新鲜黄瓜和调味恰到好处的鱼露蘸酱。分量十足的一份餐，让您充分体验西贡美食的精髓。'
WHERE Name = 'Cơm Tấm Quân Đội';

UPDATE Foods SET
Description_VI = 'Bánh canh cua với nước dùng được ninh từ cua tươi sống, vị ngọt thanh tự nhiên hòa quyện cùng sợi bánh canh mềm dẻo dai. Mỗi tô đều có thịt cua xé sợi chắc ngọt, giò heo hầm mềm nhừ, hành phi vàng giòn và rau thơm tươi xanh. Hương thơm nức mũi tỏa ra từ nồi nước dùng sôi sùng sục, tạo nên một tác phẩm ẩm thực đặc sắc của miền Trung Việt Nam.',
Description_EN = 'Crab tapioca noodle soup with broth simmered from live fresh crab, delivering a naturally sweet and clean flavor that melds perfectly with soft and chewy tapioca noodles. Each bowl features generous shredded crab meat, tender braised pork knuckle, crispy fried shallots, and fresh aromatic herbs. The intoxicating aroma rising from the bubbling broth creates a distinctive culinary masterpiece from Central Vietnam.',
Description_CN = '蟹肉木薯粉汤，用新鲜活蟹熬制的高汤，自然鲜甜的味道与软糯有嚼劲的木薯粉完美融合。每碗都有丰富的蟹肉丝、炖得软烂的猪蹄、金黄酥脆的油葱和新鲜香草。从沸腾的锅中升腾起的诱人香气，造就了这道来自越南中部的独特美食杰作。'
WHERE Name = 'Bánh Canh Cua Nha Trang';

UPDATE Foods SET
Description_VI = 'Phở đặc biệt với nước dùng vàng trong được ninh từ xương bò và các loại gia vị truyền thống suốt 12 giờ đồng hồ. Sợi phở bánh mỏng mềm mịn kết hợp hoàn hảo với thịt bò tái hồng hào, gân bò dai mềm, nạm bò thơm béo. Ăn kèm rau thơm tươi, giá đỗ giòn, chanh chua thanh và ớt cay nồng. Mỗi bát phở là câu chuyện về truyền thống ẩm thực lâu đời của Sài Gòn.',
Description_EN = 'Special pho with a clear golden broth simmered from beef bones and traditional spices for a full 12 hours. Thin, silky rice noodles combine perfectly with rose-pink rare beef, tender beef tendon, and aromatic fatty brisket. Served with fresh herbs, crunchy bean sprouts, tangy lime, and fiery chili. Each bowl of pho tells the story of Saigon''s enduring culinary heritage.',
Description_CN = '特色牛肉河粉，清澈金黄的高汤由牛骨和传统香料慢炖整整12个小时。薄而柔滑的米粉与粉嫩的半熟牛肉、软嫩的牛筋和香浓的牛腩完美搭配。配以新鲜香草、脆爽的豆芽、清爽的青柠和火辣的辣椒。每一碗河粉都诉说着西贡悠久的美食传承故事。'
WHERE Name LIKE 'Phở Đ%c Biệt%' OR Name LIKE 'Phở Đặc Biệt%';

UPDATE Foods SET
Description_VI = 'Cà phê pha theo kiểu truyền thống Sài Gòn, sử dụng hạt cà phê Robusta từ vùng cao nguyên Tây Nguyên, rang chậm lửa cho đến khi đạt độ đậm hoàn hảo. Pha qua phin nhôm cổ điển, từng giọt cà phê đen sánh nhỏ chậm rãi vào lớp sữa đặc trắng ngần bên dưới. Khuấy đều và thêm đá viên trong vắt, tạo nên ly cà phê sữa đá mát lạnh sảng khoái, thức uống biểu tượng của Sài Gòn.',
Description_EN = 'Coffee brewed in the traditional Saigon style, using premium Robusta beans from the Central Highlands of Vietnam, slow-roasted to achieve the perfect depth of flavor. Dripped through a classic aluminum phin filter, each dark, rich drop falls slowly onto a layer of sweetened condensed milk below. Stirred together and poured over crystal-clear ice cubes, creating an iconic Saigon iced milk coffee that is refreshing and invigorating.',
Description_CN = '按照西贡传统方式冲泡的咖啡，选用越南中部高原的优质罗布斯塔咖啡豆，慢火烘焙至完美醇厚。通过经典的铝制滴漏壶过滤，浓郁的黑色咖啡液缓慢滴落在下方的白色炼乳上。搅拌均匀后倒入晶莹剔透的冰块中，打造出标志性的西贡冰咖啡，清凉提神，令人回味无穷。'
WHERE Name = 'Cà Phê Truyền Thống Sài Gòn';

UPDATE Foods SET
Description_VI = 'Bánh mì Thục với vỏ bánh giòn vàng ươm vừa ra lò, nhân đa dạng phong phú từ chả lụa thơm ngon, thịt xá xíu mềm ngọt, pâté béo ngậy, dưa chua giòn sần và hành tây ngâm giấm chua cay. Mỗi ổ bánh mì được chế biến tỉ mỉ với lớp bơ mỏng phết đều, tạo nên sự cân bằng hoàn hảo giữa các hương vị mặn ngọt béo chua. Phục vụ nóng hổi ngay khi khách gọi.',
Description_EN = 'Banh Mi Thuc with a freshly baked golden crispy crust, generously filled with savory pork roll, tender sweet char siu, creamy pâté, crunchy pickled vegetables, and spicy vinegar-pickled onions. Each sandwich is meticulously crafted with a thin layer of butter spread evenly, creating a perfect harmony of salty, sweet, rich, and tangy flavors. Served piping hot the moment you order.',
Description_CN = '阿淑面包以新鲜出炉的金黄酥脆外壳为特色，内馅丰富包括香浓的越南火腿肠、软嫩微甜的叉烧、奶油般的肝酱、脆爽的腌菜和酸辣的醋腌洋葱。每个三明治都精心制作，均匀涂抹薄薄一层黄油，在咸甜浓酸之间达到完美的味觉平衡。点单即刻热腾腾地端上桌。'
WHERE Name = 'Bánh Mì Thục';

UPDATE Foods SET
Description_VI = 'Mì Quảng Minh Châu với nước dùng đậm đà được nấu từ tôm và xương heo, mì vàng béo mềm thấm đẫm nước sốt. Topping đa dạng và hào phóng gồm tôm sú tươi to bằng ngón tay, thịt heo nướng thơm lừng, trứng cút luộc, rau sống giòn mát và lạc rang vàng giòn phủ lên trên. Mỗi miếng mì quảng đều là sự kết hợp tinh tế giữa vị ngọt thanh của nước dùng và sự giòn bùi của lạc.',
Description_EN = 'Mi Quang Minh Chau with a rich broth cooked from shrimp and pork bones, yellow turmeric noodles soft and flavorful, soaked in aromatic sauce. Generously topped with large fresh tiger prawns, fragrant grilled pork, boiled quail eggs, crispy fresh greens, and golden roasted peanuts sprinkled on top. Each bite is a refined combination of the clean sweetness of the broth and the nutty crunch of peanuts.',
Description_CN = '明珠广宁面配以虾和猪骨熬制的浓郁高汤，黄色姜黄面条柔软入味，浸透在芳香的酱汁中。丰富的配料包括新鲜肥美的大虎虾、香气四溢的烤猪肉、煮鹌鹑蛋、脆嫩的生菜和撒在上面的金黄烤花生。每一口都是高汤清甜与花生香脆的精致结合。'
WHERE Name = 'Mì Quảng Minh Châu';

UPDATE Foods SET
Description_VI = 'Bún bò Huế chính hiệu xứ Quảng với nước dùng cay nồng đặc trưng, được ninh từ xương bò cùng sả, mắm ruốc và ớt chưng đỏ au. Thịt bò kho tàu mềm tan trong miệng, giò heo hầm nhừ tách xương, chả cua viên tròn chắc nịch. Sợi bún to tròn dai mềm ngập trong nước lèo đậm đà. Ăn kèm rau muống bào, bắp chuối thái mỏng và chanh ớt tươi, tái hiện trọn vẹn hương vị cố đô Huế tại Sài Gòn.',
Description_EN = 'Authentic Hue-style beef noodle soup from Quang region with its signature spicy broth, simmered from beef bones with lemongrass, fermented shrimp paste, and vibrant red chili oil. Fork-tender braised beef melts in your mouth, alongside fall-off-the-bone pork knuckle and firm round crab cakes. Thick round noodles swim in the rich, flavorful broth. Served with shredded water spinach, thinly sliced banana blossom, and fresh lime with chili — a faithful recreation of Hue''s imperial flavors in Saigon.',
Description_CN = '正宗广域风味的顺化牛肉面，标志性的辣味高汤由牛骨、香茅、虾酱和鲜红辣椒油慢炖而成。软烂入口即化的炖牛肉、骨肉分离的猪蹄和紧实圆润的蟹肉丸。粗圆的米粉浸泡在浓郁鲜美的汤底中。搭配切丝的空心菜、薄切的蕉花和新鲜的青柠辣椒，在西贡完美重现顺化古都的宫廷风味。'
WHERE Name = 'Bún Bò Huế Xứ Quảng';

UPDATE Foods SET
Description_VI = 'Bánh chưng truyền thống và bánh mì giòn xù từ bột mì tươi được nhào nặn thủ công mỗi ngày. Nhân bánh phong phú gồm pâté béo ngậy, thịt nướng than hoa thơm lừng, dưa chua giòn sật và hành lá tươi xanh. Chiên vàng giòn rụm trong dầu nóng, ăn kèm nước mắm chua ngọt pha với tỏi ớt băm nhuyễn. Sự kết hợp độc đáo giữa ẩm thực truyền thống miền Bắc và phong cách đường phố Sài Gòn.',
Description_EN = 'Traditional square sticky rice cake and super-crunchy bread made from fresh flour kneaded by hand daily. Rich fillings include creamy pâté, charcoal-grilled meat with smoky aroma, tangy pickled vegetables, and fresh green onions. Deep-fried to golden crispy perfection, served with sweet-and-sour fish sauce mixed with finely minced garlic and chili. A unique fusion of Northern Vietnamese tradition and Saigon street food style.',
Description_CN = '传统方形糯米糕和每天手工揉制新鲜面粉制成的超脆面包。丰富的馅料包括奶油般的肝酱、带有烟熏香气的炭烤肉、酸爽的腌菜和新鲜的葱花。油炸至金黄酥脆，搭配蒜末辣椒调配的酸甜鱼露蘸酱。这是越南北方传统美食与西贡街头风格的独特融合。'
WHERE Name = 'Bánh Chưng Mỳ Tươi Homeboy';

UPDATE Foods SET
Description_VI = 'Quán cà phê hiện đại với không gian sang trọng và thiết kế tối giản đầy nghệ thuật. Phục vụ cà phê chuyên nghiệp pha từ máy espresso cao cấp cùng các loại tiramisu tươi ngon được làm mới mỗi ngày. Ngoài ra còn có đa dạng các loại bánh ngọt châu Âu, smoothie trái cây nhiệt đới và đồ uống lạnh sáng tạo. Không gian lý tưởng để thưởng thức buổi chiều thư giãn cùng bạn bè.',
Description_EN = 'A modern café with an elegant ambiance and artfully minimalist design. Serving professional espresso-based coffee from premium machines alongside fresh tiramisu prepared daily. Also featuring a diverse selection of European pastries, tropical fruit smoothies, and creative cold beverages. The perfect space for a relaxing afternoon with friends.',
Description_CN = '一间装饰优雅、极简艺术设计的现代咖啡馆。提供由高端咖啡机制作的专业浓缩咖啡，以及每日新鲜制作的提拉米苏。还有多种欧式糕点、热带水果奶昔和创意冷饮可供选择。是与朋友共度悠闲午后的理想空间。'
WHERE Name = 'Tiramisu Café Vĩnh Khánh';

-- Kiểm tra kết quả
SELECT Id, Name, LEFT(Description_VI, 50) AS 'Mô tả VI (50 ký tự đầu)' FROM Foods ORDER BY Id;
SELECT CONCAT('✅ Đã cập nhật mô tả cho ', COUNT(*), ' món ăn') AS Status FROM Foods WHERE LENGTH(Description_VI) > 100;
